const BASE_URL = "http://localhost:8081/api/appointments";

// 🔥 helper to get token
const getAuthHeader = () => {
  const token = localStorage.getItem("token");
  console.log("Using TOKEN:", token);
  return {
    Authorization: `Bearer ${token}`,
  };
};

// 📌 Get logged-in user appointments
export const getMyAppointments = async () => {
  try {
    const res = await fetch(`${BASE_URL}/my`, {
      method: "GET",
      headers: {
        ...getAuthHeader(),
      },
    });

    console.log("GET /my STATUS:", res.status);

    if (!res.ok) {
      const text = await res.text();
      console.error("ERROR RESPONSE:", text);
      throw new Error("Failed to fetch appointments");
    }

    const data = await res.json();
    console.log("APPOINTMENTS DATA:", data);

    return data;
  } catch (err) {
    console.error("getMyAppointments ERROR:", err);
    throw err;
  }
};

// ❌ Cancel appointment
export const cancelAppointment = async (id) => {
  try {
    const res = await fetch(`${BASE_URL}/${id}/cancel`, {
      method: "PUT",
      headers: {
        ...getAuthHeader(),
      },
    });

    console.log("CANCEL STATUS:", res.status);

    if (!res.ok) {
      const text = await res.text();
      console.error("CANCEL ERROR:", text);
      throw new Error("Cancel failed");
    }

    const data = await res.json();
    console.log("CANCEL RESPONSE:", data);

    return data;
  } catch (err) {
    console.error("cancelAppointment ERROR:", err);
    throw err;
  }
};
